  'muscle.label':     { en:'The Core Idea', zh:'核心理念', ja:'核心アイデア', ko:'핵심 아이디어', es:'La Idea Central', fr:'L\'Idée Centrale', de:'Die Kernidee', pt:'A Ideia Central', ru:'Ключевая идея', ar:'الفكرة الأساسية', it:'L\'Idea Centrale', hi:'मुख्य विचार' },
  'muscle.title':     { en:'AI has no memory. Give it one.', zh:'AI 没有记忆。给它一个。', ja:'AIに記憶がない。与えよう。', ko:'AI에게 기억이 없습니다. 기억을 주세요.', es:'La IA no tiene memoria. Dale una.', fr:'L\'IA n\'a pas de mémoire. Donnez-lui une.', de:'KI hat kein Gedächtnis. Gib ihr eines.', pt:'A IA não tem memória. Dê uma a ela.', ru:'У ИИ нет памяти. Дайте ему память.', ar:'الذكاء الاصطناعي لا ذاكرة له. أعطِه واحدة.', it:'L\'IA non ha memoria. Dàgliene una.', hi:'AI के पास कोई याददाश्त नहीं। उसे एक दें।' },

  // ── Architecture ──
  'arch.label':       { en:'Architecture', zh:'架构', ja:'アーキテクチャ', ko:'아키텍처', es:'Arquitectura', fr:'Architecture', de:'Architektur', pt:'Arquitetura', ru:'Архитектура', ar:'البنية', it:'Architettura', hi:'आर्किटेक्चर' },
  'arch.title':       { en:'Three layers. All localhost. Zero cloud.', zh:'三层架构。全部本地。零云端。', ja:'3層構造。すべてローカル。クラウドなし。', ko:'3개 레이어. 모두 로컬. 클라우드 제로.', es:'Tres capas. Todo local. Cero nube.', fr:'Trois couches. Tout en local. Zéro cloud.', de:'Drei Schichten. Alles lokal. Null Cloud.', pt:'Três camadas. Tudo local. Zero nuvem.', ru:'Три слоя. Всё локально. Ноль облака.', ar:'ثلاث طبقات. كل شيء محلي. بدون سحابة.', it:'Tre livelli. Tutto locale. Zero cloud.', hi:'तीन लेयर। सब लोकल। ज़ीरो क्लाउड।' },

