  'article.back.tut': { en:'Back to Tutorials', zh:'返回教程', ja:'チュートリアルに戻る', ko:'튜토리얼로 돌아가기', es:'Volver a Tutoriales', fr:'Retour aux Tutoriels', de:'Zurück zu Tutorials', pt:'Voltar para Tutoriais', ru:'Назад к руководствам', ar:'العودة إلى الدروس', it:'Torna ai Tutorial', hi:'ट्यूटोरियल पर वापस जाएं' },
