  'cmp.calls':        { en:'API Calls', zh:'API 调用', ja:'API呼び出し', ko:'API 호출', es:'Llamadas API', fr:'Appels API', de:'API-Aufrufe', pt:'Chamadas API', ru:'API-вызовы', ar:'استدعاءات API', it:'Chiamate API', hi:'API कॉल' },
